-- Mage Style 2 Cryomancer replaces Mana Barrier (Q 2026-10-18: ice Mage from a Gemini draft; Q picked A/B/A on Claude's questions).
-- Chill 10% per stack, max 4, Frozen = Shatter 15% Max HP + can't Strike next turn. Frost Armor (Frostbinder's Shield 40) + Deep Freeze + Frost Barrier are the Style; Absolute Zero is the S + S + S combo under it (engine/combos.ts).
-- MG-040..043 (Claude's Frost cards) and MG-044..048 (Gemini's) are in the deck only under Cryomancer; 9 base cards leave it to keep 25.
update public.champion_styles set name = 'Cryomancer', effect = 'Frost Armor: start the game with Shield 40; every hit a Shield soaks gives the attacker 1 Chill. Deep Freeze: when you Strike with any Skill card in your chain, spend 1 more Mana to give the opponent 1 Chill. Frost Barrier: when you Block with Mana, spend 1 Mana for Shield 5 this turn; each hit your Block stops gives the attacker 1 Chill. Chill: each stack makes that side''s hits deal 10% less (3 turns, max 4). At 4 stacks the opponent is Frozen: Chill clears, Shatter takes 15% of their Max HP and they can''t Strike next turn. Absolute Zero (S + S + S all clean): the opponent is Frozen and can''t Block next turn.'
where champion_id = 'MG' and slot = 2;

update public.cards set style_only = '!MG:2' where id in ('MG-005', 'MG-006', 'MG-012', 'MG-023', 'MG-017', 'MG-022');
-- MG-008/021/025 were already out of the Pyromancer deck ('!MG:1'); out of Cryomancer too, they leave the deck (kept for the future deck builder)
update public.cards set in_deck = false where id in ('MG-008', 'MG-021', 'MG-025');

insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, style_only) values
  ('MG-040', 'MG', 'Frost Jab', 'Claude', 'Frost', 'P', 8, 'After action, if you play Strike and this card hits clean: Opponent gains 1 Chill (each stack: hits deal 10% less, 3 turns; at 4 stacks Frozen: loses 15% Max HP and can''t Strike next turn)', 1, 40, true, '{Attack,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"chill","who":"enemy","n":1}]}]'::jsonb, null, 'MG:2'),
  ('MG-041', 'MG', 'Ice Kick', 'Claude', 'Frost', 'K', 9, 'Before action, if opponent plays Strike: Facing card −3 dmg per Chill stack on opponent', 1, 41, true, '{Defend,Control}', '[{"hook":"modify","if":[{"c":"enemyAction","a":"strike"}],"do":[{"a":"addDmg","target":"facing","n":-3,"per":"enemyChill"}]}]'::jsonb, null, 'MG:2'),
  ('MG-042', 'MG', 'Cold Snap', 'Claude', 'Frost', 'S', 6, 'Before action, if you play Strike: Opponent gains 2 Chill (each stack: hits deal 10% less, 3 turns; at 4 stacks Frozen: loses 15% Max HP and can''t Strike next turn)', 1, 42, true, '{Spell,Control}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"chill","who":"enemy","n":2}]}]'::jsonb, 1, 'MG:2'),
  ('MG-043', 'MG', 'Glacial Spike', 'Claude', 'Frost', 'S', 12, 'Before action, if you play Strike: This card +3 dmg per Chill stack on opponent', 1, 43, true, '{Spell,Attack}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"addDmg","target":"this","n":3,"per":"enemyChill"}]}]'::jsonb, 2, 'MG:2'),
  ('MG-044', 'MG', 'Ice Shatter', 'Q', 'Frost', 'S', 8, 'Before action, if you play Strike and opponent is Frozen: This card +30 dmg', 1, 44, true, '{Attack,Spell}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"hasStatus","who":"enemy","kind":"frozen"}],"do":[{"a":"addDmg","target":"this","n":30}]}]'::jsonb, 2, 'MG:2'),
  ('MG-045', 'MG', 'Arcane Sub-Zero', 'Q', 'Frost', 'S', 7, 'After action, if you play Strike: Next turn, every card of yours that hits clean gives the opponent 1 Chill', 1, 45, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"status","who":"self","kind":"subZero","turns":1}]}]'::jsonb, 2, 'MG:2'),
  ('MG-046', 'MG', 'Glacial Lock', 'Q', 'Frost', 'S', 8, 'After action, if you play Strike: Opponent can''t Charge next turn', 1, 46, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"status","who":"enemy","kind":"noCharge","turns":1}]}]'::jsonb, 1, 'MG:2'),
  ('MG-047', 'MG', 'Bitter Cold', 'Q', 'Frost', 'S', 8, 'After action, if you play Strike: Opponent''s Skill cards have no effect next turn', 1, 47, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"status","who":"enemy","kind":"skillSilence","turns":1}]}]'::jsonb, 1, 'MG:2'),
  ('MG-048', 'MG', 'Blizzard Totem', 'Q', 'Frost', 'S', 5, 'Every turn (Hold): Opponent gains 1 Chill (each stack: hits deal 10% less, 3 turns; at 4 stacks Frozen: loses 15% Max HP and can''t Strike next turn)', 1, 48, true, '{Hold,Control}', '[{"hook":"onHeld","do":[{"a":"chill","who":"enemy","n":1}]}]'::jsonb, 1, 'MG:2')
on conflict (id) do update set name = excluded.name, type = excluded.type, dmg = excluded.dmg, effect = excluded.effect, effect_json = excluded.effect_json, cost = excluded.cost, style_only = excluded.style_only, in_deck = excluded.in_deck, tags = excluded.tags;

-- Molten Shield back to its first version (Q 2026-10-17 22:16Z): Block spends up to 3 Mana for Shield 5 per Mana
update public.champion_styles set effect = 'Touch of Flame: every Skill card you paid for that hits clean gives the opponent 1 Ignite (each stack burns 2 HP + 1% Max HP every turn and cuts heals 25%, max 50%; 3 turns, max 4 stacks). Molten Shield: when you Block with Mana, spend up to 3 Mana for Shield 5 per Mana this turn; each hit your Block stops gives the attacker 1 Ignite.'
where champion_id = 'MG' and slot = 1;
